import{_ as l,o as t,c as i,j as a,a as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const q=JSON.parse('{"title":"몬스터 배치 M005","description":"","frontmatter":{},"headers":[],"relativePath":"world/Monster-Batch-M005.md","filePath":"world/Monster-Batch-M005.md"}'),o={name:"world/Monster-Batch-M005.md"};function p(n,h,d,s,u,c){return t(),i("div",null,[...h[0]||(h[0]=[a("h1",{id:"몬스터-배치-m005",tabindex:"-1"},[r("몬스터 배치 M005 "),a("a",{class:"header-anchor",href:"#몬스터-배치-m005","aria-label":'Permalink to "몬스터 배치 M005"'},"​")],-1),a("p",null,"이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.",-1),a("ul",null,[a("li",null,[r("원본 앵커: "),a("code",null,"docs/game-logic/World-Narrative-Atlas.md")]),a("li",null,[r("원본 해시: "),a("code",null,"61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1")])],-1),a("h2",{id:"g03e09-·-녹고리호위",tabindex:"-1"},[r("G03E09 · 녹고리호위 "),a("a",{class:"header-anchor",href:"#g03e09-·-녹고리호위","aria-label":'Permalink to "G03E09 · 녹고리호위"'},"​")],-1),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 두 번째 정예"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>마곡 연구소 외벽 공터에서 녹고리호위는 겹겹이 걸린 녹슨 목줄 고리를 옆구리에 부딪히며 가장 오래 산 중형 성체의 왼쪽 옆을 지킨다.</p><p>어깨는 두껍고 주둥이의 흉터는 헬멧 가장자리에 긁힌 자국이며, 고리 소리는 명령을 전달하지 않. 흩어진 동료가 같은 바람 냄새로 모이게 하는 표지에 가깝다.</p><p>이 개체는 우두머리가 아니며, 선도 성체가 발걸음을 떼기 전에는 하역장 쪽으로 무리를 밀지 않는다.</p><h3 id="기원" tabindex="-1">기원 <a class="header-anchor" href="#기원" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>공사장 경비견으로 남았다가 대피 행렬에서 사람을 잃은 개체가, 폐쇄된 경비 통로의 철편 소리에 이끌려 유기견철군에 합류했다.</p><p>인식표의 보호소 코드는 H03 이도의 불완전 판독에만 남고, 현재 가족은 그 코드가 아니라 함께 자는 위치와 새끼 보호 권역으로 정해졌다.</p><h3 id="서식" tabindex="-1">서식 <a class="header-anchor" href="#서식" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>낮에는 S03 외벽과 고가 하부 그늘에 몸을 붙이고, 해동 냄새가 진해지는 밤에만 S08 야간 하역장 가장자리로 내려간다.</p><p>XT03 물류 진동이 커진 날에는 냉동. 진입로를 건너지 않고 통로 입구의 바람만 맡으며, 인파가 짙은 낮 환승 계단에는 나타나지 않는다.</p><h3 id="필요" tabindex="-1">필요 <a class="header-anchor" href="#필요" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>에너지는 생선 내장과 버려진 급식 팩의 단백질이며, 재오염되지 않은 밀폐 급수가 없으면 그늘 휴식도 오래 유지하지 못한다.</p><p>고리의 녹이 얼어 붙으면 철편 소리가 끊겨 재결속이 늦어지므로, 비나 하역 물기가 고리를 적시는 밤에는 이동을 스스로 줄인다.</p><p>HC03이 폐기 단백질을 지나치게 봉하면 이 개체는 시장 골목으로 옆을 비키지 못한 채 밀려난다.</p><h3 id="생애·정비" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>계절마다 털이 갈리며 고리 사이에 낀 염분과 비늘을 이빨로 뜯어 낸다.</p><p>강제 포획으로 고리가 잘리면 냄새만으로 선도 성체를 찾으려 며칠을 헤매고, 그 사이 새끼 가족은 별도 권역을 지킨 채 제안을 거부한다.</p><p>번식보다 영역 방어가 늘면 호위 반경만 좁아질 뿐 명령권이 생기지는 않는다.</p><h3 id="행동·위계" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체와 동행 성체 둘이 이동을 먼저 제안하면 녹고리호위는 왼쪽 외곽을 맡아 카트와 사람 체취를 가른다.</p><p>새끼가 있는 가족은 이 개체의 철편 소리를 따라오지 않을 수 있고, H03가 공격성 군집으로 묶어 기록해도 HC03 중재자는 인식표·냄새·동행 관계로 다시 나눈다.</p><h3 id="상승" tabindex="-1">상승 <a class="header-anchor" href="#상승" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에서는 공터 가장자리에서 특정 인식표와 급식차 엔진음에만 고리를 흔든다.</p><p>2단계에서는 익숙한 공회전이 여러 가족을 한 통로로 모을 때 호송 카트의 옆구리를 지키며 따라붙는다.</p><p>3단계 급식 중단이나 기만 포획 뒤에는 선도 성체와 떨어져 환승 계단과 시장 입구를 동시에 점유하는 분산 재결속에 가담한다.</p><h3 id="교전·대응" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>직사보다 차단 펜스와 소음 감소, 새끼 구역 깃발이 우선이다.</p><p>철편 소리를 거짓 미끼로 쓰면 이후 구조 호출에도 고리를 흔들지 않으며, 포획은 실제 공격을 주도한 개체와 부상에 한정해야 한다.</p><p>성공은 제거 수가 아니라 시민 교상 0건과 하역 지연 분의 감소, 가족이 다시 같은 그늘에 모이는 비율로 본다.</p><h3 id="협상·도덕-선택" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>HC03이 야간 급식 시각과 하역 개방 창을 거래할 때, 녹고리호위의 철편을 유인 신호로 쓸지 개체 대조가 끝날 때까지 기다릴지가 갈린다.</p><p>유인은 통로를 빨리 비우지만 구조 신뢰를 태우고, 대조는 하역을 늦춘다.</p><p>옛 경비 기록을 처벌 장부로 올리는 순간 이 개체의 옆구리는 사람 체취를 위협으로만 기억한다.</p><h3 id="시나리오-연결" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1에서는 불완전하게 읽힌 태그 세 개 가운데 겹고리 개체의 동행 관계를 가린다.</p><p>G03-SC2에서는 옛 급식차 엔진음에 호위 반경이 하역로로 붙고, G03-SC3에서는 냉동. 진입로를 둘러싼 분산 재결속의 외곽을 맡는다.</p><h2 id="g03e10-·-하역그늘지기" tabindex="-1">G03E10 · 하역그늘지기 <a class="header-anchor" href="#g03e10-·-하역그늘지기" aria-label="Permalink to &quot;G03E10 · 하역그늘지기&quot;">​</a></h2>',37),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 환경 거점형"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-1" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-1" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>S08 야간 하역장 그늘과 냉동 잔여 바람이 겹치는 바닥에, 하역그늘지기는 짧.</p><p>넓은 몸과 젖은 발바닥으로 휴식 자리를 고정한다.</p><p>이동하는 호위견과 달리 이 개체는 그늘 면적 자체를 지키며, 사람이 그늘을 걷어 내면 잠자리가 아니라 시장 골목의 처마로 자리가 미끄러진다.</p><p>목줄 고리는 하나뿐이나 부식된 인식표가 발에 걸려 개체 번호가 아니라 그늘의 경계 소리를 낸다.</p><h3 id="기원-1" tabindex="-1">기원 <a class="header-anchor" href="#기원-1" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>문을 닫은 사설 보호소의 급식 시간이 끊긴 뒤, 하역장 차광막 아래에서 해동 냄새와 그늘을 함께 얻은 소가족이 이 자리를 잠자리로 고정했다.</p><p>허구의 UHF 태그는 과거 우리 번호를 남길 뿐, 현재의 거점은 그늘과 밀폐 급수통의 위치다.</p><h3 id="서식-1" tabindex="-1">서식 <a class="header-anchor" href="#서식-1" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>핵심은 S08 하역 풍하측 그늘이며, 낮의 인파가 짙으면 배수구 입구까지만 물러난다.</p><p>S03 공터로 매일 왕복하지 않고, XT03 진동이 세면 그늘을 포기한 채 냉동고 벽면에 붙어 온도만 따른다.</p><h3 id="필요-1" tabindex="-1">필요 <a class="header-anchor" href="#필요-1" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>단백질 잔여보다 재오염되지 않은 물과 그늘 면적이 밀도 상한이다.</p><p>HC03이 폐기 단백질을 느슨히 두면 그늘에 가족이 과밀해져 인명 접촉이 늘고, 밀봉을 강화하면 이 개체는 그늘을 잃은 채 아동 통로 처마로 미끄러진다.</p><h3 id="생애·정비-1" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-1" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>그늘이 사흘 연속 사라지면 잠자리를 옮기고, 급수가 오염되면 해동 물웅덩이를 핥다가 소독약 냄새에 구역을 버린다.</p><p>번식은 그늘이 안정된 계절에만 시도되며, 강제 철거 뒤에는 인식표가 남은 개체를 중심으로 같은 기둥 밑으로 돌아온다.</p><h3 id="행동·위계-1" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-1" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체의 제안을 받더라도 새끼가 그늘에 있으면 따라가지 않는다.</p><p>하역 카트가 그늘을 스치면 낮은 경고만 내고, 명령권 없는 연합 안에서 이 개체는 자리의 거부권만 갖는다.</p><h3 id="상승-1" tabindex="-1">상승 <a class="header-anchor" href="#상승-1" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에서는 그늘 가장자리의 급식차에만 반응한다.</p><p>2단계에서는 엔진음이 재현되면 그늘 밖 하역로까지 가족이 붙고, 3단계 급식 중단 때는 그늘을 비운 채 환승 계단과 냉동 진입로를 동시에 점한다.</p><h3 id="교전·대응-1" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-1" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>그늘을 통째로 철거하면 거점이 골목으로 이동할 뿐이다.</p><p>급식 우회 포인트와 새끼 깃발을 그늘 옆에 두. 하역 동선을 꺾는 편이 안전하며, 성공 지표는 그늘 체류 시간과 교상 0건이다.</p><h3 id="협상·도덕-선택-1" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-1" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>하역 속도를 위해 차광막을 걷으면 시민 통행은 잠깐 열리지만 그늘 없는 가족은 시장으로 밀린다.</p><p>그늘을 남기면 밀도가 한곳에 모여 접촉 위험이 남는다.</p><p>이 거점을 투기 보관 장소로 삼는 순간 협상 창이 닫힌다.</p><h3 id="시나리오-연결-1" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-1" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1의 태그 대조는 그늘에서 함께 자는 관계를 현재 가족으로 볼지를 묻는다.</p><p>G03-SC2에서는 엔진음이 그늘 거점을 하역로로 끌어내고, G03-SC3에서는 그늘을 포기한 가족들이 냉동. 진입로를 둘러싼다.</p><h2 id="g03e11-·-고가밑잠자리" tabindex="-1">G03E11 · 고가밑잠자리 <a class="header-anchor" href="#g03e11-·-고가밑잠자리" aria-label="Permalink to &quot;G03E11 · 고가밑잠자리&quot;">​</a></h2>',34),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 환경 거점형"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-2" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-2" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>S03 고가 하부와 배수구가 만나는 건조한 턱에, 고가밑잠자리는 긴 몸통과 진흙 묻은 발톱으로 낮 잠자리를 표시한다.</p><p>하역그늘지기와 달리 이 거점은 야간 하역이 아니라 낮의 인적 밀도를 피하는 숨자리이며, 영역 소변은 지워도 같은 기둥 뿌리에 다시 남는다.</p><h3 id="기원-2" tabindex="-1">기원 <a class="header-anchor" href="#기원-2" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>군중 대피 때 헤어진 반려 개체가 연구소 담장 바깥 배수로를 따라 고가 아래로 들어왔고, 철편 소리보다 콘크리트 냉각과 그늘 습도를 잠자리의 조건으로 삼았다.</p><p>태그의 옛 주거 코드는 단서일 뿐 기둥 밑의 동행이 현재 권역이다.</p><h3 id="서식-2" tabindex="-1">서식 <a class="header-anchor" href="#서식-2" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>핵심은 S03 고가 하부이며, 하역 잔여가 늘어도 매일 S08까지 내려가지 않는다.</p><p>비가 배수구를 채우면 턱을 한 단 위로 옮기고, XT03 진동이 기둥을 흔드는 날에는 잠자리를 잠시 비운다.</p><h3 id="필요-2" tabindex="-1">필요 <a class="header-anchor" href="#필요-2" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>밀폐 급수와 건조한 턱, 적은 소독약 잔향이 유지 비용이다.</p><p>단백질은 공터에 남은 급식 팩으로 충분하나, 급수가 재오염되면 잠자리를 버리고 환승 계단의 그늘로 올라간다.</p><h3 id="생애·정비-2" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-2" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>턱의 진흙이 굳으면 발톱으로 긁어 통풍구를 만들고, 소독 차량이 지나가면 하루 동안 자리를 비운다.</p><p>새끼가 있는 주에는 선도 성체의 하역 제안을 거부하고 기둥 뿌리를 지킨다.</p><h3 id="행동·위계-2" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-2" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>명령권은 없으며, 이 개체는 잠자리의 출입 시각만 지킨다.</p><p>H03가 고가 하부를 한 군집으로 합산해도 HC03는 소변 위치와 새끼 수로 가족을 나눈다.</p><h3 id="상승-2" tabindex="-1">상승 <a class="header-anchor" href="#상승-2" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에서는 공터 가장자리 급식차에만 잠깐 나온다.</p><p>2단계 엔진음이 경비 통로에서 울리면 고가 밑 가족까지 하역로로 끌려가고, 3단계에는 잠자리를 비운 채 환승 계단을 점유한다.</p><h3 id="교전·대응-2" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-2" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>고가 하부를 물로 밀어내면 잠자리는 환승 계단으로 이동한다.</p><p>우회 화살표 옆에 소변 표식을 남기고 통행을 나누는 편이 충돌을 줄이며, 일괄 소독은 소독약 냄새를 위협 기억으로 고정한다.</p><h3 id="협상·도덕-선택-2" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-2" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>낮 통행을 위해 표식을 지우면 사람은 편해지나 개들은 경계를 잃고 계단에서 만난다.</p><p>표식을 규칙으로 남기면 시민이 우회해야 한다.</p><p>잠자리를 벌집 보관으로 쓰면 제보망이 끊긴다.</p><h3 id="시나리오-연결-2" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-2" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1에서는 고가 밑 동행이 보호소 코드보다 우선인지가 쟁점이다.</p><p>G03-SC2의 엔진음은 이 잠자리까지 흔들고, G03-SC3에서 비운 고가 밑은 환승 계단 재결속의 출발점이 된다.</p><h2 id="g03e12-·-찢긴이름표" tabindex="-1">G03E12 · 찢긴이름표 <a class="header-anchor" href="#g03e12-·-찢긴이름표" aria-label="Permalink to &quot;G03E12 · 찢긴이름표&quot;">​</a></h2>',32),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 손상 단계형"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-3" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-3" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>찢긴이름표는 목걸이 한쪽이 끊기.</p><p>수동형 UHF 태그가 젖은 털에 뒤집혀, H03가 2미터 안에서 같은 개체를 두 번 세거나 놓치는 손상 단계의 중형 개다.</p><p>걸을 때마다 끊긴 철편이 불규칙한 음을 내어 동료는 모이지만 기계 장부는 소유자를 확정하지 못한다.</p><h3 id="기원-3" tabindex="-1">기원 <a class="header-anchor" href="#기원-3" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>하역장 가장자리에서 서로 다른 보호소 코드가 읽히던 밤, 카트에 걸려 태그가 찢어졌다.</p><p>그 손상은 변이가 아니라 사고이며, 이후의 재결속은 소리와 냄새로만 이어진다.</p><h3 id="서식-3" tabindex="-1">서식 <a class="header-anchor" href="#서식-3" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S08 하역 가장자리와 S03 공터를 오가되, 금속 펜스 옆에서는 태그가 더 자주 누락되어 배수구 쪽 그늘을 택한다.</p><p>낮 인파 속 환승 계단은 피한다.</p><h3 id="필요-3" tabindex="-1">필요 <a class="header-anchor" href="#필요-3" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>해동 단백질과 밀폐 급수가 필요하나, 태그 방향을 고칠 사람의 손짓이 익숙한 급식 수레와 겹칠 때만 접근한다.</p><p>낯선 장갑 냄새는 먹이보다 위협이다.</p><h3 id="생애·정비-3" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-3" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>끊긴 고리는 재생되지 않고 털이 자라면 태그를 더 가린다.</p><p>소독 후 젖은 상태에서 판독이 최악이 되며, 마르기 전에는 장부에 유령 개체가 하나 더 생긴다.</p><h3 id="행동·위계-3" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-3" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체를 따르되 자신의 불규칙한 철편 때문에 새끼 가족이 먼저 멈춘다.</p><p>위계를 만들지 못하고, 손상음 자체가 재결속 표지이자 오판의 원인이 된다.</p><h3 id="상승-3" tabindex="-1">상승 <a class="header-anchor" href="#상승-3" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계 불완전 판독이 세 코드를 동시에 띄운다.</p><p>2단계 엔진음에 손상음이 섞이면 여러 가족이 한 카트에 붙고, 3단계 기만 포획 이후에는 이 소리만으로 계단과 시장이 동시에 점유된다.</p><h3 id="교전·대응-3" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-3" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>손상된 태그를 강제로 떼면 개체는 구조 호출을 영구히 거부한다.</p><p>외형·동행 대조를 기다리고 급식 수레로 잠시 거리를 두는 편이 안전하다.</p><h3 id="협상·도덕-선택-3" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-3" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>전자 기록의 옛 소유와 지금 함께 자는 동물 가족 중 무엇을 등록할지가 이 개체의 쟁점이다.</p><p>대조를 기다리면 하역이 늦고, 수레로 분리하면 손상음을 따라오지 못하는 새끼가 떨어지며 현재 관계 우선은 뒤늦은 반환 청구와 충돌한다.</p><h3 id="시나리오-연결-3" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-3" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1 ‘녹슨 이름표’의 한가운데에 있으며, G03-SC2에서는 손상음이 엔진음과 겹쳐 오판을 키우고 G03-SC3에서는 장부가 하나의 대장으로 합산하지 못하게 만드는 분산 표지가 된다.</p><h2 id="g03e13-·-느린선도성체" tabindex="-1">G03E13 · 느린선도성체 <a class="header-anchor" href="#g03e13-·-느린선도성체" aria-label="Permalink to &quot;G03E13 · 느린선도성체&quot;">​</a></h2>',31),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 노화 단계형"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-4" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-4" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>느린선도성체는 유기견철군에서 가장 오래 살아남은 중형 성체로, 이동을 먼저 제안하지만 영구 명령권은 없다.</p><p>뒷다리가 뻣뻣하고 고리는 녹슬어 소리가 낮으며, 동행 성체 둘이 곁을 지킬 때만 하역 바람 쪽으로 발걸음을 뗀다.</p><h3 id="기원-4" tabindex="-1">기원 <a class="header-anchor" href="#기원-4" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>사설 보호소와 공사장과 대피 행렬을 거쳐 마곡 외벽 공터에 남은 개체로, 급식 일정이 안정되자 번식보다 영역 방어를 늘렸다.</p><p>허구의 태그 이력은 여러 우리 번호를 남기나 지금 지위는 나이와 동행일 뿐이다.</p><h3 id="서식-4" tabindex="-1">서식 <a class="header-anchor" href="#서식-4" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S03 공터의 그늘 터널을 낮 잠자리로 쓰고, 하역이 늦는 밤에만 S08 입구까지 천천히 내려간다.</p><p>XT03 진동이 큰 날에는 제안을 하지 않고 터널에 머문다.</p><h3 id="필요-4" tabindex="-1">필요 <a class="header-anchor" href="#필요-4" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>부드러운 단백질과 밀폐 급수, 짧은 이동 거리가 유지 조건이다.</p><p>급식을 끊으면 제안이 시장 골목으로 바뀌고, 과밀 하역장은 관절을 더 상하게 한다.</p><h3 id="생애·정비-4" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-4" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>노화로 하역로를 왕복하는 횟수가 줄고, 동행 성체가 사라지면 48시간 가까이 같은 냄새 축을 반복해 훑는다.</p><p>강제 포획 뒤 남은 인식표만으로 재편을 강요하면 새끼 가족이 먼저 흩어진다.</p><h3 id="행동·위계-4" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-4" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>제안은 하되 새끼 권역의 거부를 받는다.</p><p>H03가 이 개체를 컨트롤러로 찍어도 HC03 중재자는 동행 관계로 다시 나누며, 학살 명령은 적지 않는다.</p><h3 id="상승-4" tabindex="-1">상승 <a class="header-anchor" href="#상승-4" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에서는 공터 가장자리의 익숙한 수레에만 천천히 붙는다.</p><p>2단계 엔진음에는 동행 둘과 함께 하역로로 나오고, 3단계 급식 중단 때는 제안이 통로 분할 실패로 끝나 계단과 시장이 동시에 점유된다.</p><h3 id="교전·대응-4" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-4" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>노령 개체를 먼저 포획하면 무리는 해산된 것이 아니라 분산된다.</p><p>우회 수레와 그늘 연장, 짧은 개방 창이 우선이며 성공은 선도가 터널 밖으로 나왔다가 가족이 따라오는 비율로 본다.</p><h3 id="협상·도덕-선택-4" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-4" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>하역을 위해 느린 제안을 기다릴지, 부상·노령을 비살상 포획해 통로를 빨리 열지가 갈린다.</p><p>기다림은 식품 지연을 남기고, 포획은 신뢰를 태워 구조 호출을 죽인다.</p><p>원 운전자 한 사람에게 이 개체의 신뢰를 몰아주는 것도 취약성을 남긴다.</p><h3 id="시나리오-연결-4" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-4" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC1에서는 오래된 태그와 현재 선도 위치를 대조하는 대상이 되고, G03-SC2에서는 엔진음을 기억하는 중심이며 G03-SC3에서는 제안이 거부된 뒤에도 학살 없이 구역 급식을 열 것인지가 이 개체에 걸린다.</p><h2 id="g03e14-·-수레곁들개" tabindex="-1">G03E14 · 수레곁들개 <a class="header-anchor" href="#g03e14-·-수레곁들개" aria-label="Permalink to &quot;G03E14 · 수레곁들개&quot;">​</a></h2>',31),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 공존형"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-5" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-5" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>수레곁들개는 부드러운 입과 낮게 흔드는 꼬리, 급식 수레 바퀴살에 익숙한 어깨 흉터를 가진 공존형이다.</p><p>사람 손짓과 특정 엔진 공회전을 안전으로 학습했으나, 그 사람이 사라지면 먹이를 거부하거나 카트 타이어를 문다.</p><h3 id="기원-5" tabindex="-1">기원 <a class="header-anchor" href="#기원-5" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>폐쇄된 경비 통로의 급식차를 따라 살아남은 개체로, 허구의 재결속 규칙은 차량 소리와 수레 냄새를 동료 표지와 같은 층에 올려 두었다.</p><p>실재 보호소 비난의 근거는 되지 않는다.</p><h3 id="서식-5" tabindex="-1">서식 <a class="header-anchor" href="#서식-5" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S03 경비 통로 입구와 S08 하역로 사이를 수레와 함께 오가며, 수레가 없는 낮에는 고가 하부에 숨는다.</p><p>아동 통로에는 스스로 들어가지 않으나 급식이 끊기면 그 금이 깨진다.</p><h3 id="필요-5" tabindex="-1">필요 <a class="header-anchor" href="#필요-5" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>익숙한 수레의 바퀴음, 정해진 시각의 급식 팩 소독약보다 약한 사람 체취가 필요하다.</p><p>이동식 급식소가 매일 자리를 바꾸면 따라가지만 냉장 인력 비용을 사람에게 전가한다.</p><h3 id="생애·정비-5" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-5" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>새 운전자의 냄새를 며칠에 걸쳐 학습하며, 그 기간 하역량을 줄여야 공격이 줄는다.</p><p>기만 포획에 한 번 당하면 같은 수레에도 접근하지 않는다.</p><h3 id="행동·위계-5" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-5" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>선도 성체보다 수레를 먼저 보고, 새끼 가족에게 수레 옆 자리를 양보한다.</p><p>지휘자가 아니라 신뢰의 매듭이며, 매듭이 한 사람에게 몰리면 연합 전체가 취약해진다.</p><h3 id="상승-5" tabindex="-1">상승 <a class="header-anchor" href="#상승-5" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에서는 특정 수레에만 붙는다.</p><p>2단계 엔진음 재현에 흩어진 가족이 하역로로 모이고, 3단계 급식 중단 때는 수레 없는 계단을 점유한다.</p><h3 id="교전·대응-5" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-5" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>수레를 미끼 우리로 쓰면 공존형이 즉시 적대형으로 바뀐다.</p><p>원래 운전자를 찾거나 새 운전자를 단계적으로 익히거나, 엔진음 없는 이동식 급식소를 쓰는 세 길이 있으며 총구는 해법이 아니다.</p><h3 id="협상·도덕-선택-5" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-5" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>원 운전자 의존은 즉시 통로를 비우나 한 사람의 부재가 합의를 무너뜨린다.</p><p>재학습은 여러 날의 하역 손실을 치르고, 무음 급식소는 신뢰 신호를 보존하나 매일의 인력과 냉장이 든다.</p><p>신뢰를 소모품으로 다루면 이후의 모든 구조가 무력하다.</p><h3 id="시나리오-연결-5" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-5" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC2 ‘급식차를 기억하는 무리’의 핵심이며, G03-SC1의 태그 대조 때 수레 옆 동행이 증거가 되고 G03-SC3에서는 가족별 급식 구역을 여는 매듭으로 남는다.</p><h2 id="g03e15-·-환승재결속핵" tabindex="-1">G03E15 · 환승재결속핵 <a class="header-anchor" href="#g03e15-·-환승재결속핵" aria-label="Permalink to &quot;G03E15 · 환승재결속핵&quot;">​</a></h2>',31),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 시나리오 보스"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-6" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-6" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>환승재결속핵은 한 마리의 독재자가 아니라, 여러 가족의 인식표 소리와 체취가 냉동.</p><p>진입로에 겹칠 때 생기는 시나리오 보스 국면의 중심 성체다.</p><p>몸집은 중형이나 철편 음이 겹고리·손상음·낮은 선도음과 한꺼번에 울려, H03 로그에는 단일 군락으로 찍힌다.</p><h3 id="기원-6" tabindex="-1">기원 <a class="header-anchor" href="#기원-6" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>XT03 물류 진동과 급식 중단이 겹친 밤에, 마곡 공터와 노량진 하역과 고가 밑에서 온 소가족들이 같은 진입로를 둘러싸며 이 국면이 생겼다.</p><p>창작된 재결속망이지 전설의 우두머리 혈통이 아니다.</p><h3 id="서식-6" tabindex="-1">서식 <a class="header-anchor" href="#서식-6" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>최고 단계에서는 S08 냉동고 진입로와 환승 계단 참을 동시에 점하고, 평시에는 S03 그늘 터널로 다시 흩어진다.</p><p>낮 인파 속에서는 핵이 보이지 않는다.</p><h3 id="필요-6" tabindex="-1">필요 <a class="header-anchor" href="#필요-6" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>가족별 급식 구역과 밀폐 저장분, 부상 개체를 돌볼 그늘이 없으면 핵은 해산되지 않고 더 넓은 생활권으로 퍼진다.</p><p>단백질을 한곳에 쏟아도 권역이 나뉘지 않으면 과밀만 커진다.</p><h3 id="생애·정비-6" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-6" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>이 국면은 개체의 수명이 아니라 신뢰가 무너진 시간의 길이다.</p><p>기만 포획 후 엔진음과 수레를 일정 기간 퇴역시키지 않으면 핵은 같은 시각에 다시 모인다.</p><h3 id="행동·위계-6" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-6" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>고정 지휘는 없고, 가족별 거부권이 선도 제안보다 강하다.</p><p>센서가 하나로 합산해도 중재자는 잠자리·새끼 수·출입 시각으로 쪼개야 한다.</p><h3 id="상승-6" tabindex="-1">상승 <a class="header-anchor" href="#상승-6" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1·2단계를 건너뛴 듯 보여도 실제로는 기억 확인과 재결속이 쌓인 끝이다.</p><p>3단계에서 시장 입구, 환승 계단 냉동 진입로가 동시에 막히며 총격은 생활권만 넓힌다.</p><h3 id="교전·대응-6" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-6" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>일괄 포획과 학살 명령은 금지에 가깝다.</p><p>가족별 급식 구역, 부상만의 비살상 포획 야간 하역의 다른 냉동. 이전이 대응의 세 축이고 성과는 통행 회복 속도와 교상 0 재결속 비율이다.</p><h3 id="협상·도덕-선택-6" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-6" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>구역 운영은 동물의 사회적 기억을 지키나 배급 인력과 저장분을 태운다.</p><p>제한 포획은 신뢰 손상을 줄이나 통행 회복이 느리고, 하역 이전은 상인의 냉동 비용을 높인다.</p><p>사람의 통행권을 위해 동물의 현재 가족을 지울 수 있는지가 도덕 비용이다.</p><h3 id="시나리오-연결-6" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-6" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC3 ‘환승 계단의 재결속’의 보스 국면이며, G03-SC1의 태그 오판과 G03-SC2의 엔진음 학습이 겹쳐 이 핵을 만든다.</p><p>학살 명령을 적지 않고 그늘 터널만 연장하는 선택이 공존의 하한이다.</p><h2 id="g03e16-·-해협하역개" tabindex="-1">G03E16 · 해협하역개 <a class="header-anchor" href="#g03e16-·-해협하역개" aria-label="Permalink to &quot;G03E16 · 해협하역개&quot;">​</a></h2>',33),a("ul",null,[a("li",null,"그룹: G03"),a("li",null,"역할군: 지역 변종"),a("li",{"states:[S03,S08],houses:[HC03],theaters:[XT03],synthetics:[H03],scenarios:[G03-SC1,G03-SC2,G03-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-7" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-7" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>해협하역개는 마곡 공터의 마른 먼지 대신 S08 수산 하역의 소금 바람과 XT03 물류 진동에 맞춰 밤 동선을 늘린 지역 변종이다.</p><p>발바닥은 항상 젖어 있고 인식표 부식이 빠르며, 연구소 담장 쪽 가족보다 냉동 해동 냄새에 먼저 반응한다.</p><h3 id="기원-7" tabindex="-1">기원 <a class="header-anchor" href="#기원-7" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>해협삼로 쪽 진동이 커지자 하역장 입구를 따라 확장한 소가족으로, 같은 철군 호칭을 쓰되 공터 선도와는 잠자리를 공유하지 않는다.</p><p>창작된 지역 적응이며 실재 항만 사고의 설명이 아니다.</p><h3 id="서식-7" tabindex="-1">서식 <a class="header-anchor" href="#서식-7" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>야간 S08 하역 축과 냉동고 벽면이 핵심이고, 낮에는 시장 뒤 배수구에 숨는다.</p><p>S03 공터에는 폭풍 뒤의 잔여가 줄 때만 잠시 올라간다.</p><h3 id="필요-7" tabindex="-1">필요 <a class="header-anchor" href="#필요-7" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>생선 내장과 냉동 잔여가 주식이며, 밀봉이 강화되면 즉시 시장 골목으로 스며든다.</p><p>밀폐 급수는 하역 호스로 재오염되기 쉬워 별도의 그늘 통이 필요하다.</p><h3 id="생애·정비-7" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-7" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>염분에 고리가 빨리 녹아 철편음이 높아지고, 그 음이 공터 가족과 어긋나 재결속이 늦다.</p><p>하역 주기가 안정되면 번식보다 입구 방어가 늘고, 진동이 끊기면 동선이 짧아진다.</p><h3 id="행동·위계-7" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-7" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>마곡 선도 성체의 제안을 항상 따르지 않으며, 하역 축의 소가족이 따로 이동 시각을 정한다.</p><p>H03가 한 무리로 합산하면 서로 다른 피난 방향을 놓친다.</p><h3 id="상승-7" tabindex="-1">상승 <a class="header-anchor" href="#상승-7" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계 하역 가장자리의 태그 반응, 2단계 진동과 엔진음에 입구 밀집 3단계 급식 중단 때 냉동 진입로 봉쇄로 커진다.</p><p>공터 쪽과 동시에 터지면 환승 계단까지 겹친다.</p><h3 id="교전·대응-7" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-7" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>공터용 펜스를 하역장에 그대로 옮기면 젖은 바닥에서 미끄러질 뿐이다.</p><p>하역 개방 창과 골목 봉인, 내장 잔여의 밀폐를 하역 장부에 묶어야 하며 총성은 시장으로 밀어 넣는다.</p><h3 id="협상·도덕-선택-7" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-7" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>이 변종을 별 가족으로 인정하면 급식 구역이 늘고 상인 비용이 오른다.</p><p>한 무리로 합산해 한꺼번에 몰아내면 하역은 잠깐 열리지만 아동 통로가 대체 서식이 된다.</p><p>진동 시간표를 지나치게 공개하면 절도 집단이 빈 창고를 읽는다.</p><h3 id="시나리오-연결-7" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-7" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G03-SC3의 물류 진동 축에 직접 연결되고, G03-SC1의 서로 다른 보호소 코드 중 하역 코드를 남기며 G03-SC2의 엔진음 학습을 하역 호스로 변형한다.</p><h2 id="g04e01-·-마른굴연장암컷" tabindex="-1">G04E01 · 마른굴연장암컷 <a class="header-anchor" href="#g04e01-·-마른굴연장암컷" aria-label="Permalink to &quot;G04E01 · 마른굴연장암컷&quot;">​</a></h2>',31),a("ul",null,[a("li",null,"그룹: G04"),a("li",null,"역할군: 통제자"),a("li",{"states:[S04,S09],houses:[HC04,HP01],theaters:[XT04],synthetics:[H04],scenarios:[G04-SC1,G04-SC2,G04-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-8" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-8" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>마른굴연장암컷은 하수너구리족의 이름 있는 통제자이나, 전투 지휘가 아니라 새끼 이동과 좁은 통과 지점의 우선권만 갖는다.</p><p>수염이 길고 발바닥에 관로 녹이 배어 있으며, 펌프 기동 전 압력 변화를 몸으로 읽고 높은 환기실로 먼저 오른다.</p><h3 id="기원-8" tabindex="-1">기원 <a class="header-anchor" href="#기원-8" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>중랑·탄천 간선 점검이 끊긴 뒤 S04 펌프 옆 건조 대피공에 정착한 가족군의 연장자 암컷이다.</p><p>펌프보다 먼저 수위를 아는 규칙은 허구이며 실재 지자체 사고 귀속은 하지 않는다.</p><h3 id="서식-8" tabindex="-1">서식 <a class="header-anchor" href="#서식-8" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>핵심은 S04 펌프장 연결 관로의 마른 굴과 공방 하부 대피공이다.</p><p>홍수위가 오르면 S09 송신 지하 갤러리로 새끼를 옮기고, XT04 한파에는 유일한 마른 접근로를 다른 가족과 겹쳐 쓴다.</p><h3 id="필요-8" tabindex="-1">필요 <a class="header-anchor" href="#필요-8" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>수생 먹이와 유기 쓰레기, 사체 잔여가 에너지이며 낮은 유속과 건조 은신처가 유지 비용이다.</p><p>HC04가 준설을 건너뛰면 먹이막이 두꺼워져 밀도가 오르고, 과준설하면 이 암컷이 지상 시장으로 새끼를 민다.</p><h3 id="생애·정비-8" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-8" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>건기에는 가족마다 은신처를 따로 쓰고, 강우 전 선행 압력에 환기실로 옮긴다.</p><p>은신처가 연속 수몰되면 시간 분할을 포기하고 골목으로 분산한다.</p><p>우선권은 세습 혈통이 아니라 살아남은 경험이다.</p><h3 id="행동·위계-8" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-8" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>다른 가족에게 전투 명령을 내리지 않는다.</p><p>H04 로봇이 열원을 단일 군락으로 합산해도 HC04 배수 당직은 잠자리와 출입 시각으로 쪼개며, 인간 육안이 최종이다.</p><h3 id="상승-8" tabindex="-1">상승 <a class="header-anchor" href="#상승-8" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계 비가 오기 전 환기실 이동이 비공식 경보가 된다.</p><p>2단계 배설·미생물막이 수위 센서를 가려 점검 로봇과 충돌하고, 3단계 한파·홍수에 마른 관 하나에서 펌프 정비와 피난이 경합한다.</p><h3 id="교전·대응-8" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-8" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>독먹이와 전면 수몰은 사체 부패로 하류와 노동자를 함께 해친다.</p><p>부분 차수, 대체 은신 관 센서 세척 야간 지상 통행 제한이 기본이며 성공은 펌프 회복 시간과 센서 신뢰도 지상 교상 0건이다.</p><h3 id="협상·도덕-선택-8" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-8" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>너구리 이동을 예비 경보로 채택하면 준비 시간을 벌지만 오탐 책임이 남고, HP01 수문가의 측정을 기다리면 급한 유입에 늦을 수 있다.</p><p>두 신호가 다를 때만 펌프를 예열하면 연료는 아끼나 짧은 국지 호우를 놓친다.</p><p>비공식 생태 신호에 공공 안전을 맡길지가 이 통제자의 도덕 비용이다.</p><h3 id="시나리오-연결-8" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-8" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G04-SC1 ‘맨홀 아래의 선행지표’의 중심 이동을 만들고, G04-SC2에서는 준설창과 겹치는 시간 분할의 한쪽 가족 우선권을 가지며 G04-SC3 한파의 마른 통로에서 난방 은신 관·점검 지연·외부 발판 중 하나를 강제한다.</p><h2 id="g04e02-·-관로순회너구리" tabindex="-1">G04E02 · 관로순회너구리 <a class="header-anchor" href="#g04e02-·-관로순회너구리" aria-label="Permalink to &quot;G04E02 · 관로순회너구리&quot;">​</a></h2>',32),a("ul",null,[a("li",null,"그룹: G04"),a("li",null,"역할군: 일반 생태형"),a("li",{"states:[S04,S09],houses:[HC04],theaters:[XT04],synthetics:[H04],scenarios:[G04-SC1,G04-SC2,G04-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-9" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-9" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>관로순회너구리는 하수너구리족의 일반 생태형으로, 낮에는 맨홀 아래 관로에 숨고 밤에는 출구에서 약 50미터 안의 골목을 돈다.</p><p>수염으로 물살과 틈의 공기 흐름을 읽고, 청각으로 펌프 진동과 장화 소리를 가르며 전투용 발톱이 아니라 젖은 털과 좁은 어깨가 몸이다.</p><h3 id="기원-9" tabindex="-1">기원 <a class="header-anchor" href="#기원-9" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>수생 먹이와 쓰레기, 사체를 따라 사람이 비운 빗물 간선에 들어온 가족군의 평범한 성체다.</p><p>도시 하천 출현이라는 현실 범위만 참고하고, 관로 운영에 개입하는 질서는 허구다.</p><h3 id="서식-9" tabindex="-1">서식 <a class="header-anchor" href="#서식-9" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>S04 낮은 유속 관로가 기본이며, 수위가 오르면 S09 환기구 쪽으로 잠시 분산한다.</p><p>한파에 사료 밀도가 바뀌면 동부 지선으로 이동했다가 해빙 뒤 익숙한 관으로 돌아온다.</p><h3 id="필요-9" tabindex="-1">필요 <a class="header-anchor" href="#필요-9" aria-label="Permalink to &quot;필요&quot;">​</a></h3><p>미생물막과 유기 쓰레기, 사체 잔여가 먹이이고 건조한 은신처가 없으면 지상 체류가 길어진다.</p><p>준설이 한꺼번에 먹이막을 걷으면 이 개체부터 시장 골목으로 밀려 난다.</p><h3 id="생애·정비-9" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-9" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>건기에는 자기 가족의 먹이터만 돌고, 홍수 뒤에는 시간대를 나눠 같은 간선을 쓴다.</p><p>좁은 관에 유리한 작은 체구가 세대를 넘어 남을 수는 있으나 지상 횡단과 한파에는 더 약해진다.</p><p>며칠 만의 피난처 변경은 유전이 아니라 학습이다.</p><h3 id="행동·위계-9" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-9" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>연장자 암컷의 우선권을 통과 지점에서만 인정하고, 그 외에는 자기 시간표를 따른다.</p><p>로봇 로그가 부유 잔해와 이 개체를 혼동하므로 사람이 확인하기 전에는 군락 수로 세지 않는다.</p><h3 id="상승-9" tabindex="-1">상승 <a class="header-anchor" href="#상승-9" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계 강우 전 높은 환기실로 따라 오르고, 2단계 센서가 가려진 관에서 점검 로봇과 마주치며 3단계 마른 관이 하나일 때 펌프 접근로에 겹친다.</p><h3 id="교전·대응-9" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-9" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>골목에서 몰아내면 50미터 순회가 주거 현관으로 짧아질 뿐이다.</p><p>야간 통행 창을 나누고 대체 은신 관을 열며 센서를 씻는 일이 대응이고, 살처분은 수질을 더 망친다.</p><h3 id="협상·도덕-선택-9" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-9" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>50미터 골목을 통행 금지 창으로 나누면 사람은 불편하고 너구리는 관로에 남는다.</p><p>지상 몰아내기는 즉시 민원을 줄이나 주거 침입을 늘린다.</p><p>질병 공포의 독살은 관로 노동자와 하류 식수를 함께 위험에 빠뜨리고 선행지표 종을 잃는다.</p><h3 id="시나리오-연결-9" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-9" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G04-SC1에서는 암컷을 따라 환기실로 오르는 일반 개체로 경보의 밀도를 만들고, G04-SC2 준설창이 깨지면 지상 시장으로 나오는 첫 물결이 되며 G04-SC3에서는 세 가족 중 한 줄로 마른 통로에 겹친다.</p>',30)])])}const S=l(o,[["render",p]]);export{q as __pageData,S as default};
